-- ✅ Check of TASK 3 – generated by the teacher's build script, do not edit.
-- It compares a summary (md5) of your model customer_signup with the expected one: PASS = your rows are right.
-- FAIL: the rows differ – compare rows_found with rows_expected and re-read the task.
-- ERROR: usually a column is missing or named differently – the columns must be: full_name, email, city, country, channel, signup_date_raw.
with summary as (
    select count(*) as n, md5(coalesce(string_agg(concat_ws('|', full_name, email, city, country, channel, signup_date_raw), E'\n' order by concat_ws('|', full_name, email, city, country, channel, signup_date_raw) collate "C"), '')) as h from {{ ref('customer_signup') }}
)
select n as rows_found, 36 as rows_expected
from summary
where h <> 'b4bb301569fda0d838050ff12d3579f0'
